import{_ as a,o as t,c as p,a3 as s}from"./chunks/framework.DdpBa4_E.js";const r="/ReadBooks/assets/image-028.POw7RKaI.jpg",o="/ReadBooks/assets/image-020.BlppwfRp.jpg",_="/ReadBooks/assets/image-044.B8MYI5ry.jpg",g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/69-团块世代是下向渗透式消费的主要市场.md","filePath":"books/xialiu-shehui/69-团块世代是下向渗透式消费的主要市场.md","lastUpdated":1794732511000}'),i={name:"books/xialiu-shehui/69-团块世代是下向渗透式消费的主要市场.md"};function l(n,e,d,c,u,m){return t(),p("div",null,[...e[0]||(e[0]=[s('<h2 id="团块世代是下向渗透式消费的主要市场" tabindex="-1">团块世代是下向渗透式消费的主要市场 <a class="header-anchor" href="#团块世代是下向渗透式消费的主要市场" aria-label="Permalink to &quot;团块世代是下向渗透式消费的主要市场&quot;">​</a></h2><p>为了更加明确团块次代的消费行为特征，我们来比较一下他们与团块世代男性之间的差异。</p><p>首先从兴趣来看，团块世代的男性阶层越往“上”，对旅游或休闲、驾车旅行、骑车旅游以及棒球等感兴趣的人越多（见表6-15）。而团块次代的男性对驾车旅行及骑车旅游的爱好没有阶层的差异，但对于棒球则是阶层越往“下”喜爱的人数越多。也就是说，团块世代在兴趣方面的价值取向与团块次代正好相反。</p><p>表6-15　不同阶层团块世代男性的兴趣爱好（主要选项）</p><p><img src="'+r+'" alt="" loading="lazy"></p><p>资料出处：Culture Studies研究所、e-FALCON共同实施的“欲求调查”</p><p>此外，关于自己喜欢的车，团块世代的上流阶层大多列举本田“NSX”、日产“SKYLINE”“奔驰”“宝马”等运动型轿车和进口车。正是这群具有强烈的阶层上升志向的消费者，自二战之后一直牵引着日本消费市场的发展（见表6-16）。</p><p>表6-16　不同阶层团块世代男性所喜欢的车（主要选项）</p><p><img src="'+o+'" alt="" loading="lazy"></p><p>资料出处：Culture Studies研究所、e-FALCON共同实施的“欲求调查”</p><p>而团块世代中流阶层喜欢的车则多为丰田“皇冠”、丰田“Celsior”、日产“CIMA”等日本高档国产车，他们以能够拥有这样的车而兴奋不已，这说明他们向上流阶层迈进的欲望已经成为一股不断扩大的消费力量。</p><p>相比之下，昭和初年世代中喜欢丰田“皇冠”、丰田“Celsior”的则以上流阶层居多；而昭和初年世代的中流阶层则更喜爱丰田“MARK II”、丰田“花冠”。也就是说，阶层意识与车的等级之间存在着一定的相关关系（见表6-17）。</p><p>表6-17　不同阶层昭和初年世代男性所喜欢的车（主要选项）</p><p><img src="'+_+'" alt="" loading="lazy"></p><p>资料出处：Culture Studies研究所、e-FALCON共同实施的“欲求调查”</p><p>换言之，在选择自己喜欢的车方面，昭和初年世代上流阶层的选项到了团块世代这一代已经降格为中流阶层的选项，这可以说是典型的下向渗透式（trickle-down）消费（即社会财富或流行趋向从“上流”波及、渗透到“下流”的一种消费样式）。中流阶层复制并学会了上流阶层的消费志向，憧憬着买更高价、更高级的东西，厂商的销售额和利润也因此不断扩大。</p><p>至于团块世代的上流阶层则关注起更高级的进口车或充满运动感的轿车（轿跑车）。对于汽车厂商而言，团块世代仍是一个潜力非常大的市场。</p><p>本书由“<a href="http://epubw.com" target="_blank" rel="noreferrer">ePUBw.COM</a>”整理，<a href="http://epubw.com" target="_blank" rel="noreferrer">ePUBw.COM</a> 提供最新最全的优质电子书下载！！！</p>',18)])])}const f=a(i,[["render",l]]);export{g as __pageData,f as default};
